package com.pellicciotta.support.annotations;

import java.lang.annotation.*;

import com.pellicciotta.support.utils.DateTimeUtils;

/**
 *  Annotation that can be applied to mark sources code that was generated by a tool and hence clearly indicate
 *  that this generated source should not be changed as it might get re-generated and then all manual adaptations
 *  would get overwritten.
 *  <p>
 *  This annotation should be used in favor of <code>javax.annotation.Generated</code> as this latter type
 *  will no longer be available in JDK11.</p>
 */
@Documented
@Retention(RetentionPolicy.SOURCE)
@Target({ ElementType.PACKAGE, ElementType.TYPE, ElementType.ANNOTATION_TYPE, ElementType.METHOD,
          ElementType.CONSTRUCTOR, ElementType.FIELD, ElementType.LOCAL_VARIABLE, ElementType.PARAMETER })
public @interface Generated {
  /**
   * @return The value element MUST have the name of the code generator.
   */
  String value();

  /**
   * @return Any additional comments.
   */
  String comments() default "";

  /**
   * @return Date when the source was generated.
   *         <p>
   *         The date should be in UTC and in the {@link DateTimeUtils#DEFAULT_DATETIME_FORMAT} or {@link DateTimeUtils#ISO_8601_DATETIME_FORMAT} format,
   *         so either <code>yyyy-MM-dd HH:mm:ss</code> or <code>yyyy-MM-ddTHH:mm:ss</code>.
   *         It may end with <code>Z</code> to more clearly indicate that it represents UTC time.</p>
   */
  String date() default "";
}
